import React from 'react';

export default function PageHeader({ title, subtitle, eyebrow }) {
    return (
        <div
            style={{
                background:
                    'radial-gradient(circle at 20% 0%, rgba(16,185,129,0.12), transparent 50%), #0F1525',
                borderBottom: '1px solid rgba(148,163,184,0.15)',
                padding: '70px 0 50px',
                textAlign: 'center',
            }}
        >
            <div className="container">
                {eyebrow && (
                    <span
                        style={{
                            color: '#10B981',
                            fontWeight: 600,
                            letterSpacing: 1.5,
                            textTransform: 'uppercase',
                            fontSize: '0.8rem',
                        }}
                    >
                        {eyebrow}
                    </span>
                )}
                <h1 style={{ fontSize: '2.6rem', margin: '10px 0 12px' }}>{title}</h1>
                {subtitle && (
                    <p className="muted" style={{ maxWidth: 640, margin: '0 auto', fontSize: '1.05rem' }}>
                        {subtitle}
                    </p>
                )}
            </div>
        </div>
    );
}
